we could export the util/json#convertMapNumbers method, and do this in the patcher:

```diff
diff --git a/staging/src/k8s.io/apiserver/pkg/endpoints/handlers/patch.go b/staging/src/k8s.io/apiserver/pkg/endpoints/handlers/patch.go
index a043bb3b251..f25a904e656 100644
--- a/staging/src/k8s.io/apiserver/pkg/endpoints/handlers/patch.go
+++ b/staging/src/k8s.io/apiserver/pkg/endpoints/handlers/patch.go
@@ -17,6 +17,7 @@ limitations under the License.
 package handlers

 import (
+       gojson "encoding/json"
        "context"
        "fmt"
        "net/http"
@@ -434,7 +435,15 @@ func (p *applyPatcher) applyPatchToCurrentObject(obj runtime.Object) (runtime.Ob
        }

        patchObj := &unstructured.Unstructured{Object: map[string]interface{}{}}
-       if err := yaml.Unmarshal(p.patch, &patchObj.Object); err != nil {
+       if err := yaml.Unmarshal(p.patch, &patchObj.Object, func(d *gojson.Decoder) *gojson.Decoder {
+               // preserve int/float distinctions
+               d.UseNumber()
+               return d
+       }); err != nil {
+               return nil, errors.NewBadRequest(fmt.Sprintf("error decoding YAML: %v", err))
+       }
+       // convert json.Number to ints or floats
+       if err := json.ConvertMapNumbers(patchObj.Object,0); err != nil {
                return nil, errors.NewBadRequest(fmt.Sprintf("error decoding YAML: %v", err))
        }
```

An alternative approach could be using `k8s.io/apimachinery/pkg/util/json` and `k8s.io/apimachinery/pkg/util/yaml` to convert yaml into json and then unmarshal. WDYT?

```diff
diff --git a/staging/src/k8s.io/apiserver/pkg/endpoints/handlers/patch.go b/staging/src/k8s.io/apiserver/pkg/endpoints/handlers/patch.go
index 81e112b070e..8b4b91f111e 100644
--- a/staging/src/k8s.io/apiserver/pkg/endpoints/handlers/patch.go
+++ b/staging/src/k8s.io/apiserver/pkg/endpoints/handlers/patch.go
@@ -38,6 +38,7 @@ import (
        "k8s.io/apimachinery/pkg/util/sets"
        "k8s.io/apimachinery/pkg/util/strategicpatch"
        "k8s.io/apimachinery/pkg/util/validation/field"
+       "k8s.io/apimachinery/pkg/util/yaml"
        "k8s.io/apiserver/pkg/admission"
        "k8s.io/apiserver/pkg/audit"
        "k8s.io/apiserver/pkg/authorization/authorizer"
@@ -49,7 +50,6 @@ import (
        "k8s.io/apiserver/pkg/util/dryrun"
        utilfeature "k8s.io/apiserver/pkg/util/feature"
        utiltrace "k8s.io/utils/trace"
-       "sigs.k8s.io/yaml"
 )

 const (
@@ -434,9 +434,13 @@ func (p *applyPatcher) applyPatchToCurrentObject(obj runtime.Object) (runtime.Ob
        }

        patchObj := &unstructured.Unstructured{Object: map[string]interface{}{}}
-       if err := yaml.Unmarshal(p.patch, &patchObj.Object); err != nil {
+       jsonBytes, err := yaml.ToJSON(p.patch)
+       if err != nil {
                return nil, errors.NewBadRequest(fmt.Sprintf("error decoding YAML: %v", err))
        }
+       if err := json.Unmarshal(jsonBytes, &patchObj.Object); err != nil {
+               return nil, errors.NewBadRequest(fmt.Sprintf("error decoding json: %v", err))
+       }

        return p.fieldManager.Apply(obj, patchObj, p.options.FieldManager, force)
 }
```

I am not sure which approach is better to be honest, `convertMapNumbers` seems a bit low-level to be called here, but I am happy  to go with either.
